import numpy as npimport matplotlib.pyplot as pltimport time, statisticsfrom numba import njitimport pyopencl as cl# ── Numba kernels ──────────────────────────────────────────────────────────────@njitdef mandelbrot_point_numba(c, max_iter):    z = 0j    for n in range(max_iter):        if z.real*z.real + z.imag*z.imag > 4.0:            return n        z = z*z + c    return max_iter@njitdef mandelbrot_numba_typed(xmin, xmax, ymin, ymax, width, height, max_iter, dtype=np.float64):    x = np.linspace(xmin, xmax, width).astype(dtype)    y = np.linspace(ymin, ymax, height).astype(dtype)    result = np.zeros((height, width), dtype=np.int32)    for i in range(height):        for j in range(width):            cr = x[j]                      ci = y[i]            zr = dtype(0.0)            zi = dtype(0.0)            for n in range(max_iter):                zr2 = zr * zr                zi2 = zi * zi                if zr2 + zi2 > dtype(4.0):                    result[i, j] = n                    break                zi = dtype(2.0) * zr * zi + ci                zr = zr2 - zi2 + cr            else:                result[i, j] = max_iter    return result# ── OpenCL kernel ──────────────────────────────────────────────────────────────KERNEL_32 = """__kernel void mandelbrot_fp32(    __global int *result,    const float x_min, const float x_max,    const float y_min, const float y_max,    const int N, const int max_iter){    int col = get_global_id(0);    int row = get_global_id(1);    if (col >= N || row >= N) return;    float c_real = x_min + col * (x_max - x_min) / (float)N;    float c_imag = y_min + row * (y_max - y_min) / (float)N;    float zr = 0.0f, zi = 0.0f;    int count = 0;    while (count < max_iter && zr*zr + zi*zi <= 4.0f) {        float tmp = zr*zr - zi*zi + c_real;        zi = 2.0f * zr * zi + c_imag;        zr = tmp;        count++;    }    result[row * N + col] = count;}"""# ── Config ─────────────────────────────────────────────────────────────────────N        = 1024MAX_ITER = 200X_MIN, X_MAX = -2.5, 1.0Y_MIN, Y_MAX = -1.25, 1.25N_RUNS   = 3# ── Setup OpenCL ───────────────────────────────────────────────────────────────ctx   = cl.create_some_context(interactive=False)queue = cl.CommandQueue(ctx)prog  = cl.Program(ctx, KERNEL_32).build()image     = np.zeros((N, N), dtype=np.int32)image_dev = cl.Buffer(ctx, cl.mem_flags.WRITE_ONLY, image.nbytes)def run_gpu(n):    prog.mandelbrot_fp32(        queue, (n, n), None,        image_dev,        np.float32(X_MIN), np.float32(X_MAX),        np.float32(Y_MIN), np.float32(Y_MAX),        np.int32(n), np.int32(MAX_ITER),    )    queue.finish()# ── Helper: time N_RUNS after one warmup ──────────────────────────────────────def bench(label, warmup_fn, run_fn):    print(f"\n── {label} ──")    warmup_fn()    print("  warmup done")    times = []    for i in range(N_RUNS):        t0 = time.perf_counter()        run_fn()        times.append(time.perf_counter() - t0)        print(f"  run {i+1}: {times[-1]*1e3:.1f} ms")    med = statistics.median(times) * 1e3    print(f"  median : {med:.1f} ms")    return med# ── Numba: trigger JIT compile first (counts as warmup) ───────────────────────print("Compiling Numba kernels (first call = JIT warmup)…")mandelbrot_numba_typed(X_MIN, X_MAX, Y_MIN, Y_MAX, 64, 64, MAX_ITER, dtype=np.float32)mandelbrot_numba_typed(X_MIN, X_MAX, Y_MIN, Y_MAX, 64, 64, MAX_ITER, dtype=np.float64)print("Done.\n")# ── Benchmark Numba f32 ───────────────────────────────────────────────────────med_numba_f32 = bench(    "Numba CPU  f32",    warmup_fn=lambda: mandelbrot_numba_typed(        X_MIN, X_MAX, Y_MIN, Y_MAX, N, N, MAX_ITER, dtype=np.float32),    run_fn=lambda: mandelbrot_numba_typed(        X_MIN, X_MAX, Y_MIN, Y_MAX, N, N, MAX_ITER, dtype=np.float32),)# ── Benchmark Numba f64 ───────────────────────────────────────────────────────med_numba_f64 = bench(    "Numba CPU  f64",    warmup_fn=lambda: mandelbrot_numba_typed(        X_MIN, X_MAX, Y_MIN, Y_MAX, N, N, MAX_ITER, dtype=np.float64),    run_fn=lambda: mandelbrot_numba_typed(        X_MIN, X_MAX, Y_MIN, Y_MAX, N, N, MAX_ITER, dtype=np.float64),)# ── Benchmark GPU f32 ─────────────────────────────────────────────────────────med_gpu_f32 = bench(    "GPU OpenCL f32",    warmup_fn=lambda: run_gpu(64),    run_fn=lambda: run_gpu(N),)# ── Summary ───────────────────────────────────────────────────────────────────print("\n══════════════════════════════════════════")print(f"  {'Backend':<20} {'Median (ms)':>12}")print("──────────────────────────────────────────")print(f"  {'Numba CPU  f32':<20} {med_numba_f32:>12.1f}")print(f"  {'Numba CPU  f64':<20} {med_numba_f64:>12.1f}")print(f"  {'GPU OpenCL f32':<20} {med_gpu_f32:>12.1f}")print("══════════════════════════════════════════")